const { test, describe } = require('node:test')
const assert = require('node:assert')
const fs = require('node:fs')
const path = require('node:path')

const packageDir = path.join(__dirname, '..')
const loaderSource = fs.readFileSync(path.join(packageDir, 'index.js'), 'utf8')
const esmSource = fs.readFileSync(path.join(packageDir, 'index.mjs'), 'utf8')

const FUNCTIONS = [
  'getDisplaySize',
  'initSimulation',
  'isModifierKey',
  'normalizeKeyName',
  'simulateEvent',
  'startListener',
  'stopListener',
  'stringKeyToKeycode',
]
const ENUMS = ['ButtonType', 'EventTypeValue', 'KeyCode', 'NormalizedModifier']

describe('rdev-node modules', () => {
  test('CommonJS require works and exposes the full public API', () => {
    const rdev = require('../index.js')
    for (const fn of FUNCTIONS) {
      assert.strictEqual(typeof rdev[fn], 'function', `Missing function: ${fn}`)
    }
    for (const e of ENUMS) {
      assert.strictEqual(typeof rdev[e], 'object', `Missing enum: ${e}`)
    }
  })

  test('generated loaders are stock napi-rs output', () => {
    for (const [file, source] of [
      ['index.js', loaderSource],
      ['index.mjs', esmSource],
    ]) {
      assert.ok(source.includes('auto-generated by NAPI-RS'), `${file} is not generated output`)
    }
    assert.ok(loaderSource.includes('module.exports'), 'index.js must be CommonJS')
    assert.ok(esmSource.includes("from 'module'"), 'index.mjs must use createRequire')
    assert.ok(esmSource.includes('export { startListener }'), 'index.mjs must re-export the API')
  })

  test('exact host .node loads', () => {
    const rdev = require('../index.js')
    // A real native binding stamps its flavor; any fallback would differ.
    assert.strictEqual(rdev.__napiBindingTarget, 'native')
    // The same object comes back on repeat require: one load, cached.
    assert.strictEqual(require('../index.js'), rdev)
    // Host artifact naming: <binary>.<platformArchABI>.node next to the loader.
    const siblings = fs.readdirSync(packageDir).filter((file) => file.endsWith('.node'))
    assert.ok(siblings.length >= 1, 'expected at least the host .node next to the loader')
    assert.ok(
      siblings.every((file) => file.startsWith('node-rdev.')),
      `unexpected .node names: ${siblings.join(', ')}`,
    )
  })

  test('ESM entry matches the CommonJS binding', async () => {
    const cjs = require('../index.js')
    const esm = await import('rdev-node')
    for (const name of [...FUNCTIONS, ...ENUMS]) {
      assert.strictEqual(esm[name], cjs[name], `ESM/CJS mismatch: ${name}`)
    }
  })

  test('stopListener releases and restart after stop works', (t) => {
    const rdev = require('../index.js')
    try {
      rdev.initSimulation()
    } catch (e) {
      t.skip(`No display available: ${e.message}`)
      return
    }
    assert.strictEqual(rdev.stopListener(), false)
    rdev.startListener(() => {})
    assert.strictEqual(rdev.stopListener(), true)
    // Stopping releases the listener (and its TSFN): starting again must
    // succeed instead of hitting the duplicate-start guard.
    rdev.startListener(() => {})
    assert.strictEqual(rdev.stopListener(), true)
    assert.strictEqual(rdev.stopListener(), false)
  })
})
